#!/usr/bin/env python3
"""trunk_requires.py -- for each generated file ($WK/gen/{YE23,YD1y,YE37}.v, after nsW.py), list every module it
Requires from the unit's own namespaces and whether the trunk clone holds it:
  lib.<dir>.<M>  -> $TR/projects/reac-repacer/fuzz_wire/proofs/lib/<dir>/<M>.v
  images.<M>     -> $TR/projects/reac-repacer/fuzz_wire/images/<M>.v, or a dune rule that builds <M>.v from the
                    matching pinned binary (the images modules are generated by elf-snapshot at build time)
Read-only.  Prints one line per file plus the missing list; exit 0.
"""
import os
import re
import subprocess

WK = os.environ['WK']
TR = os.environ['TR']
U = TR + '/projects/reac-repacer/fuzz_wire/proofs'
IMG = TR + '/projects/reac-repacer/fuzz_wire/images'
REQ = re.compile(r'From (OssFuzzTheorems\.(?:Proofs\.reac_repacer\.fuzz_wire\.lib|reac_repacer\.fuzz_wire\.images))'
                 r'(?:\.(\w+))? Require(?:\s+Import|\s+Export)?\s+([\w.\'\s]+?)\.(?=\s|$)')
head = subprocess.run(['git', '-C', TR, 'rev-parse', 'HEAD'], capture_output=True, text=True).stdout.strip()
dune = open(IMG + '/dune').read() if os.path.exists(IMG + '/dune') else ''
print('trunk clone HEAD %s; unit tree %s' % (head, 'projects/reac-repacer/fuzz_wire/proofs'))
for f in ('YE23', 'YD1y', 'YE37'):
    t = open('%s/gen/%s.v' % (WK, f)).read()
    have, miss, rule = [], [], []
    for m in REQ.finditer(t):
        for n in m.group(3).split():
            if 'images' in m.group(1):
                lab = 'images.%s' % n
                if os.path.exists('%s/%s.v' % (IMG, n)):
                    have.append(lab)
                elif re.search(r'\(targets %s\.v ' % re.escape(n), dune):
                    rule.append(lab)
                else:
                    miss.append(lab)
            else:
                lab = 'lib.%s.%s' % (m.group(2), n)
                (have if os.path.exists('%s/lib/%s/%s.v' % (U, m.group(2), n)) else miss).append(lab)
    print('%s: %d unit modules Required; trunk holds %d %s; built by an images dune rule %d %s; MISSING %d: %s'
          % (f, len(have) + len(miss) + len(rule), len(have), ' '.join(have), len(rule), ' '.join(rule),
             len(miss), ' '.join(miss)))
